<?php
declare(strict_types=1);namespace Joomleague\Module\Eventranking\Site\Helper;defined('_JEXEC')or die;
use Joomla\CMS\Factory;use Joomla\Database\DatabaseInterface;use Joomla\Registry\Registry;use Joomleague\Component\Joomleague\Domain\Service\EventRankingReader;
final class EventrankingHelper{/** @return array<string,mixed> */public function getRanking(Registry$p):array{$id=(int)$p->get('project_id',0);if($id<1)return['error'=>'MOD_JOOMLEAGUE_EVENTRANKING_NO_PROJECT'];Factory::getApplication()->bootComponent('com_joomleague');$l=Factory::getLanguage();$l->load('com_joomleague',JPATH_SITE)||$l->load('com_joomleague',JPATH_SITE.'/components/com_joomleague');try{$code=trim((string)$p->get('event_code',''))?:null;return(new EventRankingReader(Factory::getContainer()->get(DatabaseInterface::class)))->forProject($id,$code,min(100,max(1,(int)$p->get('limit',5))),Factory::getApplication()->getIdentity()->getAuthorisedViewLevels());}catch(\Throwable){return['error'=>'MOD_JOOMLEAGUE_EVENTRANKING_UNAVAILABLE'];}}}
